CREATE OR REPLACE FUNCTION safe_register_user(p_email TEXT, p_name TEXT)
RETURNS BOOLEAN AS $$
BEGIN
    INSERT INTO users (email, name) VALUES (p_email, p_name);
    RETURN true;
EXCEPTION
    WHEN unique_violation THEN
        RAISE NOTICE 'Email % is already registered.', p_email;
        RETURN false;
    WHEN OTHERS THEN
        RAISE WARNING 'Unexpected error: %', SQLERRM;
        RETURN false;
END;
$$ LANGUAGE plpgsql;
